/** Serialize a {@link BugReport} to a Markdown string for the clipboard. */
import type { BugReport } from './types'

export function reportToMarkdown(report: BugReport): string {
  const list = (items: string[]) =>
    items.length > 0 ? items.map((i) => `- ${i}`).join('\n') : '_None noted_'

  return [
    `# ${report.title || 'Untitled bug report'}`,
    '',
    '> Draft generated by a local vision-language model. Review before filing.',
    '',
    '## Description (observable)',
    report.description || '_Not provided_',
    '',
    '## Visible error messages',
    report.visibleErrors ? '```\n' + report.visibleErrors + '\n```' : '_None visible_',
    '',
    '## Affected UI elements',
    list(report.affectedElements),
    '',
    `## Suggested severity`,
    report.severity,
    '',
    '## Missing information',
    list(report.missingInformation),
    '',
  ].join('\n')
}
